SELECT a.*, b.guoku_dscr, d.`NAME`, ( SELECT f.ENUM_DSCR FROM `enumset`.`cm_guoku_enumeration` f WHERE f.ENUM_TYPE_ID = '12' AND f.ENUM_ID = e.INSPECTION_TASK_TYPE ) AS INSPECTION_TASK_TYPE_DSCR FROM inspection.inspection_case a JOIN dmcode.cm_guoku_dimnsn b ON a.INSPECTED_GUOKU_ID = b.guoku_id JOIN inspection.inspection_sysuser_talentpool_relation c ON a.ADD_USER = c.SYS_USERID JOIN inspection.cm_guoku_talentpool d ON c.TALENTPOOL_ID = d.UUID LEFT JOIN inspection.inspection_task e on a.INSPECTION_TASK_ID = e.INSPECTION_TASK_ID WHERE 1 = 1
AND a.ID = #{params.ID}
AND a.INSPECTION_TASK_ID = #{params.INSPECTION_TASK_ID}
AND a.QUESTION_CONTENT like '%${params.QUESTION_CONTENT}%'
AND a.ADD_USER = #{params.ADD_USER}
AND a.QUESTION_ID_1 = #{params.QUESTION_ID} or a.QUESTION_ID_2 = #{params.QUESTION_ID}
AND a.APPROVAL_STATE = #{params.APPROVAL_STATE}
AND e.INSPECTION_TASK_TYPE = #{params.INSPECTION_TASK_TYPE}
order by a.ADD_TIME DESC LIMIT ${params.page},${params.rows}

SELECT
count(*)
FROM
inspection.inspection_case a
JOIN inspection.inspection_task e on a.INSPECTION_TASK_ID = e.INSPECTION_TASK_ID
WHERE
1 = 1

    AND a.ID = #{params.ID}


    AND a.INSPECTION_TASK_ID = #{params.INSPECTION_TASK_ID}


    AND a.QUESTION_CONTENT like '%${params.QUESTION_CONTENT}%'


    AND a.QUESTION_ID_1 = #{params.QUESTION_ID} or a.QUESTION_ID_2 = #{params.QUESTION_ID}


    AND a.APPROVAL_STATE = #{params.APPROVAL_STATE}


    AND e.INSPECTION_TASK_TYPE = #{params.INSPECTION_TASK_TYPE}

SELECT a.*, b.guoku_dscr, d.`NAME`, ( SELECT f.ENUM_DSCR FROM `enumset`.`cm_guoku_enumeration` f WHERE f.ENUM_TYPE_ID = '12' AND f.ENUM_ID = e.INSPECTION_TASK_TYPE ) AS INSPECTION_TASK_TYPE_DSCR FROM inspection.inspection_case a JOIN dmcode.cm_guoku_dimnsn b ON a.INSPECTED_GUOKU_ID = b.guoku_id JOIN inspection.inspection_sysuser_talentpool_relation c ON a.ADD_USER = c.SYS_USERID JOIN inspection.cm_guoku_talentpool d ON c.TALENTPOOL_ID = d.UUID JOIN inspection.inspection_task e on a.INSPECTION_TASK_ID = e.INSPECTION_TASK_ID WHERE 1 = 1
AND a.ID = #{params.ID}
AND a.INSPECTION_TASK_ID = #{params.INSPECTION_TASK_ID}
AND a.QUESTION_CONTENT like '%${params.QUESTION_CONTENT}%'
AND a.ADD_USER = #{params.ADD_USER}
AND a.QUESTION_ID_1 = #{params.QUESTION_ID} or a.QUESTION_ID_2 = #{params.QUESTION_ID}
AND a.APPROVAL_STATE = #{params.APPROVAL_STATE}
AND e.INSPECTION_TASK_TYPE = #{params.INSPECTION_TASK_TYPE}
order by a.ADD_TIME DESC

